// sleep-watch test, run with: node lib/node_modules/sleep-watch/test.js
// a frozen process looks the same from inside as a sleeping laptop, so it freezes child processes with SIGSTOP
// for 3 seconds and resumes them with SIGCONT, once on node and once on bare. no real sleep needed.
// to try it with a real suspend: bare lib/node_modules/sleep-watch/test.js real, then systemctl suspend, wake up, ctrl+c
const sleep_watch = require('./')

const runtime = typeof Bare === 'undefined' ? 'node' : 'bare'
const argv = runtime === 'bare' ? require('bare-process').argv : process.argv
const FREEZE = 3000
let failed = 0

if (argv[2] === 'child') watch_like_a_bot()
else if (argv[2] === 'alone') sleep_watch({ on_sleep: () => console.log('slept') })
else if (argv[2] === 'real') log_real_sleep()
else main()

async function main () {
  // 1. no false alarm while nothing happens
  const seen = []
  const watch = sleep_watch({ on_sleep: info => seen.push(info), before_sleep: done => done() })
  await wait(1500)
  watch.stop()
  check('1. watching for 1.5s without a freeze calls on_sleep 0 times (and node just skips before_sleep)', seen.length === 0)
  const { spawn } = require('child_process')
  for (const [name, bin] of [['node', process.execPath], ['bare', 'bare']]) {
    // 2. the watch alone doesnt keep a process running
    const alone = await run_child({ spawn, bin, mode: 'alone' })
    check(`2. ${name}: a process with only the watch exits by itself (${alone.ms}ms, code ${alone.code})`, alone.code === 0 && alone.ms < 1500)
    // 3. freeze a child for 3s, it has to report a gap of about 3s once it runs again
    const frozen = await run_child({ spawn, bin, mode: 'child', freeze: FREEZE })
    const gap = Number((frozen.out.match(/slept (\d+)/) || [])[1])
    check(`3. ${name}: frozen for ${FREEZE}ms, on_sleep reported a gap of ${gap}ms`, gap >= FREEZE && gap < FREEZE + 1000)
  }
  console.log(failed ? `${failed} failed` : 'all good')
  if (failed) process.exit(1)
}

/***************************************
CHILD
***************************************/
// like a bot: something keeps the process running, the watch reports the sleep and then it ends
function watch_like_a_bot () {
  const keep_alive = setTimeout(() => {}, 20000)
  const watch = sleep_watch({ on_sleep })
  console.log('ready')
  function on_sleep ({ gap }) {
    console.log(`slept ${gap}`)
    watch.stop()
    clearTimeout(keep_alive)
  }
}

// for a real suspend, prints when each callback runs. the bot pretends to need 1s to stop
function log_real_sleep () {
  setInterval(() => {}, 60000) // keeps it running till ctrl+c
  sleep_watch({ on_sleep, before_sleep })
  console.log(`${new Date().toISOString()} watching, now suspend the machine`)
  function before_sleep (done) {
    console.log(`${new Date().toISOString()} before_sleep, stopping the bot`)
    setTimeout(done, 1000)
  }
  function on_sleep ({ gap }) { console.log(`${new Date().toISOString()} on_sleep, slept ${gap}ms`) }
}

/***************************************
RUN CHILD
starts this file again in another process, freezes it for `freeze` ms if asked, resolves with its output
***************************************/
function run_child ({ spawn, bin, mode, freeze }) {
  const start = Date.now()
  // detached gives it its own process group, so the freeze also hits the real bare behind the npm `bare` launcher
  const child = spawn(bin, [__filename, mode], { detached: true })
  const state = { out: '' }
  // a child that never ends gets killed, so the test fails instead of hanging
  const limit = setTimeout(() => process.kill(-child.pid, 'SIGKILL'), (freeze || 0) + 5000)
  child.stdout.on('data', on_data)
  return new Promise(wait_for_exit)
  function on_data (data) {
    state.out += data
    if (freeze && String(data).includes('ready')) freeze_child()
  }
  async function freeze_child () {
    await wait(300)
    if (child.exitCode !== null) return
    process.kill(-child.pid, 'SIGSTOP')
    await wait(freeze)
    process.kill(-child.pid, 'SIGCONT')
  }
  function wait_for_exit (resolve) {
    child.on('error', err => resolve({ code: err.code, ms: 0, out: '' }))
    child.on('exit', on_exit)
    function on_exit (code) {
      clearTimeout(limit)
      resolve({ code, ms: Date.now() - start, out: state.out })
    }
  }
}

/***************************************
HELPERS
***************************************/
function check (name, ok) {
  console.log(`${ok ? 'ok' : 'not ok'} ${name}`)
  if (!ok) failed++
}

function wait (ms) { return new Promise(resolve => setTimeout(resolve, ms)) }
